import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%8D%E3%83%83%E3%83%88%E3%82%B9%E3%83%BC%E3%83%91%E3%83%BC.html","title":"ネットスーパー","lang":"en-US","frontmatter":{},"git":{"createdTime":1686370193000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":9}]},"readingTime":{"minutes":2.48,"words":743},"filePathRelative":"ネットスーパー.md"}`),a={name:`ネットスーパー.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="ネットスーパー" tabindex="-1"><a class="header-anchor" href="#ネットスーパー"><span>ネットスーパー</span></a></h1><p><a href="./食事関連.html">食事関連</a>の買い物は、楽天、ヨドバシなどに頼っているが、果物などが箱で買うのはやや不満もあり、 もうちょっと一週間に一回くらいで買えないかなぁ、と思って、ネットスーパーをたまに調べたりしている。（2023-06-06 (火)）</p><h2 id="関連ブログ" tabindex="-1"><a class="header-anchor" href="#関連ブログ"><span>関連ブログ</span></a></h2><ul><li><a href="https://karino2.github.io/2026/10/05/palsystem_to_rakuten_mart.html" target="_blank" rel="noopener noreferrer">palsystemから楽天マートに乗り換えた - なーんだ、ただの水たまりじゃないか</a></li></ul><h2 id="果物を買う要件" tabindex="-1"><a class="header-anchor" href="#果物を買う要件"><span>果物を買う要件</span></a></h2><p>箱で買うのは、</p><ul><li>同じ果物が続くので飽きる</li><li>後半腐らないように結構頑張って食べる必要がある</li><li>届くのにかかる時間がばらつきがある</li><li>まぁまぁ邪魔</li></ul><p>というあたりに不満があり、 一週間分くらいをその時にお買い得な果物を買って過ごしたいよなぁ、という思いがあるし、種類はいろいろ混ぜたい。 ただ果物は結構かさばるし、毎週買い物に行くなんて嫌なので通販にしたい。</p><p>一週間単位で買うので価格は2000円前後になりそう。このくらいで許せる価格だと理想だが、もう少し別に違うものも買って少し一回の額を上げる事は出来るかもしれない。</p><h2 id="ネットスーパーの手数料雑記" tabindex="-1"><a class="header-anchor" href="#ネットスーパーの手数料雑記"><span>ネットスーパーの手数料雑記</span></a></h2><p>以前の住居ではイオンとSEIYUが300円くらいの手数料で頼めたのだけれど、 新居はこの辺が範囲外（イオンはめっちゃ高い）で、手頃な代替が無いかなぁ、と調べている。</p><p>駅前には東急ストアが（何故か）あり、これはネットスーパーもやっていて送料が鎌倉店では一律550円とか。 微妙に高い。</p><p>と思っていたら、この前道でCO-OPの車を見かけた。CO-OPってどうなんだろう？おうちコープというのがそれっぽい。</p><h2 id="rakutenマート" tabindex="-1"><a class="header-anchor" href="#rakutenマート"><span>Rakutenマート</span></a></h2><p>お買い物応援プランというのに入らないと送料が1000円以上で使い物にならないが、お買い物応援プランに入っていると3500円までは330円、それ以上は無料となり、 お買い物応援プランは月550円だけどRakuten Mobile加入者は全額ポイントバックなので毎月550円が550ポイントになる。</p><p>果物はAmazonより品揃えは多く、値段はAmazonのより高いのも安いのもある。同じくらいか？</p><p>送料的にはうちが範囲の奴の中では一番安いな。</p><h3 id="使ってみた-2026-09-26-土" tabindex="-1"><a class="header-anchor" href="#使ってみた-2026-09-26-土"><span>使ってみた 2026-09-26 (土)</span></a></h3><p>13時に注文で翌日の朝が指定出来る感じだった（翌日夜受け取りにした）。すぐ届くのはありがたいな。</p><p>果物は結構売り切れがあった。どういうタイミングで決まるのかな？時間帯？曜日？</p><p>今回買った果物とかだと3500円に微妙に届かなく、普段は買わないヨーグルトとかを足した。 palsystemは5000円以上で送料110円で、まぁまぁ5000円買ってるような気もするのだが。</p><h3 id="変更が直前まで出来るのがいい" tabindex="-1"><a class="header-anchor" href="#変更が直前まで出来るのがいい"><span>変更が直前まで出来るのがいい</span></a></h3><p>住所が前の住所になっている事に気づき慌ててキャンセル。取り消しは半日前くらいまでは無料だった。 ついでに足したいとおもったものを後から追加していく。これもまぁまぁ直前まで出来るのがいいね。</p><p>時間や届け先の変更は出来ないが、キャンセルした後にキャンセルしたものでもう一回頼む、みたいなメニューがある。 キャンセルは無料なのでこれは実質変更になる。これなら変更ってUIにしてくれてもいいのでは？という気もするけれど、 このもう一度注文のメニューでも用は足りる。この辺をちゃんとやるのはいいサービスだな。</p><p>やはり<a href="./おうちコープ.html">おうちコープ</a>系は一週間前というのがネックだよなぁ。</p><h3 id="届いたもののpalsystemとの比較" tabindex="-1"><a class="header-anchor" href="#届いたもののpalsystemとの比較"><span>届いたもののpalsystemとの比較</span></a></h3><p>palsystem（<a href="./おうちコープ.html">おうちコープ</a>にまとめてある）を解約して乗り換えるかの検討のために、比較してみる。 まずは届いた時点で見ただけの印象から。食べたあとに更新する予定。</p><p><strong>楽天マートの方が良いもの</strong></p><ul><li>グレープフルーツ</li><li>豆腐</li></ul><p><strong>palsystemの方が良いもの</strong></p><ul><li>キウイ</li><li>りんご</li><li>柿</li></ul><p><strong>変わらないもの</strong></p><ul><li>梨</li><li>バナナ</li></ul><p>キウイは小さくてpalsystemに比べるといまいち（差は微妙だけど）。柿も高い割に小さい。 グレープフルーツはpalsystemに無い週なので楽天マートが良い所だな。</p><p>梨は同じくらいに見える。梨は当たり外れが多いので比較は難しいし食べてみないと分からない所もあるが。</p><p>楽天マートはりんごが売り切れていたがpalsystemはりんごの選択肢が多い。これはpalsystemの方が良い。</p><p>全体的には果物はpalsystemの方が充実しているといえるが、楽天マートの方が良いものもある。 そして木曜のおうちコープと併用するなら梨とグレープフルーツとバナナだけでいいのでは？という話もある。</p><p>そして送料無料が3500円なのは、なんだかんだで毎週700円くらい足して5000円以上にして送料110円にしているpalsystemより安上がりにしやすい。</p><p>食べて良ければ乗り換えたい。</p><h2 id="おうちコープ" tabindex="-1"><a class="header-anchor" href="#おうちコープ"><span>おうちコープ</span></a></h2><p><a href="./おうちコープ.html">おうちコープ</a>へ。</p><h2 id="amazonネットスーパーライフ" tabindex="-1"><a class="header-anchor" href="#amazonネットスーパーライフ"><span>Amazonネットスーパーライフ</span></a></h2><p>定番のネットスーパーが配送外の僻地に住んでいるのだが、 Amazonのネットスーパーライフが範囲内っぽい。 Prime会員のみっぽいので以前調べた時は気づかなかったが、今はプライム会員なので使えるようになった。</p><p>送料は8000円以上無料、2000円～8000円までは390円。</p><p>値段はふつうにライフで買うのと同じくらいに見えて結構安い。 ヨーグルトとか普段の<a href="./おうちコープ.html">おうちコープ</a>より40円くらい安い気がする。豆腐も20円くらい安い。 最寄りのスーパーと同じくらいで、隣町の一番安いスーパーよりはちょっと高い、くらい。 全体的に<a href="./おうちコープ.html">おうちコープ</a>より一回り安い印象。 2000円分くらい買えば差額は送料くらいにはなっているかもしれない。</p><p>果物の品ぞろえはいまいち。</p><p>配送がめちゃ早い。朝に頼むと午後には届く。時間指定は2時間単位（追加で500円払うと1時間単位で指定できる）</p><h3 id="使ってみた-2024-05-02-木" tabindex="-1"><a class="header-anchor" href="#使ってみた-2024-05-02-木"><span>使ってみた 2024-05-02 (木)</span></a></h3><p>試しに一回使ってみた。9:50にポチって、夜受け取りで。</p><p>18:00～20:00を指定したが、少し遅れて20:30頃に着いた。 面白いのが、配達に出ました、とか、遅れます、という通知がAmazonのアプリから来る。 非常に優れている。</p><p>この朝に指定して夜受け取れる、というのは便利で良い。 自分の場合、波の状況を見て一日の予定が決まるので、翌日の予定、というのは分からない事がある。 だから朝決めて夜に届くのはありがたい。買い物に行く感覚で買える。</p><p>Amazonで普通に買い物をするのと同じ感じでアカウントを作ったりする必要もなく、住所を登録する必要もない（Amazonに登録されているので）。 本当にすぐ使い始められるので、とても体験が良い。 Amazonとは良く統合されているなぁ、と感心した。</p><p>この辺のスーパーでは手に入らないお気に入りのカフェオレなどが買えたり、 普通にスーパーの選択肢としても良い。</p><p>という事で使ってみたら割と満足度が高かったので、今後も<a href="./おうちコープ.html">おうちコープ</a>の補助として使っていこうという気になった。</p>`,54)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};